import networkx as nx
import itertools

G = nx.Graph()
edges = [(0, 5), (0, 7), (0, 14), (1, 6), (1, 10), (1, 15), (2, 3), (3, 15), (4, 11), (5, 15), (6, 13), (7, 12), (8, 9), (8, 11), (9, 12), (11, 15), (12, 13)]
G.add_edges_from(edges)

# Check all simple cycles of length <8 using networkx's cycle_basis? No, that gives basis.
# Let's use a proper simple cycle enumeration for small lengths.
# We'll enumerate all simple paths of length k (k edges) and check if the endpoints are adjacent.

def has_short_cycle(G, maxlen):
    # Check for cycles of length <= maxlen
    # For each vertex, do BFS up to depth maxlen//2, and check for collisions.
    # Actually, we can just use the standard girth algorithm.
    from collections import deque
    n = G.number_of_nodes()
    best = float('inf')
    for s in range(n):
        dist = {s: 0}
        parent = {s: -1}
        q = deque([s])
        while q:
            u = q.popleft()
            if dist[u] * 2 >= best:  # can't find shorter cycle
                break
            for v in G.neighbors(u):
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif v != parent[u]:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < best:
                        best = cycle_len
                        # print(f"Cycle length {cycle_len}: {s}...{u}-{v}")
    return best

best = has_short_cycle(G, 7)
print("Shortest cycle length:", best)

